{"version":3,"file":"WaterfallList.js","sources":["components/WaterfallList.vue","../../../HBuilderX/plugins/uniapp-cli-vite/uniComponent:/RDovdW5pYXBwL215Sm9pbnVwL2pvaW51cC9jb21wb25lbnRzL1dhdGVyZmFsbExpc3QudnVl"],"sourcesContent":["<template>\n  <view class=\"waterfall-container\">\n    <!-- 左列 -->\n    <view class=\"column\">\n      <view\n        v-for=\"(item, index) in leftList\"\n        :key=\"item.id || `left-${index}`\"\n        class=\"display-card\"\n        @click=\"handleClick(item)\"\n      >\n        <!-- 封面图 + 标题浮层 -->\n        <view class=\"cover-wrapper\">\n          <image\n            class=\"cover-image\"\n            :src=\"item.cover || defaultCover\"\n            mode=\"aspectFill\"\n            :lazy-load=\"true\"\n          />\n          <view class=\"overlay\">\n            <view class=\"title\" v-html=\"highlight(item.name)\"></view>\n          </view>\n        </view>\n\n        <!-- 信息内容 -->\n        <view class=\"info-section\">\n          <view class=\"display-field\">\n            <text class=\"field-name\">简介：</text>\n            <view class=\"field-value\">{{ item.description }}</view>\n          </view>\n\n          <view class=\"display-field\">\n            <text class=\"field-name\">人数：</text>\n            <text class=\"field-value\">\n              {{ item.currentMembersCount }}/{{ item.maxMembers }}\n            </text>\n          </view>\n\n          <!-- 创建者信息 -->\n          <view class=\"creator-info\">\n            <image\n              class=\"creator-avatar\"\n              :src=\"item.creatorAvatar || defaultAvatar\"\n              mode=\"aspectFill\"\n            />\n            <text class=\"creator-name\">{{ item.creatorUserName || '匿名用户' }}</text>\n          </view>\n        </view>\n      </view>\n    </view>\n\n    <!-- 右列（同上） -->\n    <view class=\"column\">\n      <view\n        v-for=\"(item, index) in rightList\"\n        :key=\"item.id || `right-${index}`\"\n        class=\"display-card\"\n        @click=\"handleClick(item)\"\n      >\n        <view class=\"cover-wrapper\">\n          <image\n            class=\"cover-image\"\n            :src=\"item.cover || defaultCover\"\n            mode=\"aspectFill\"\n            :lazy-load=\"true\"\n          />\n          <view class=\"overlay\">\n            <view class=\"title\" v-html=\"highlight(item.name)\"></view>\n          </view>\n        </view>\n\n        <view class=\"info-section\">\n          <view class=\"display-field\">\n            <text class=\"field-name\">简介：</text>\n            <view class=\"field-value\">{{ item.description }}</view>\n          </view>\n\n          <view class=\"display-field\">\n            <text class=\"field-name\">人数：</text>\n            <text class=\"field-value\">\n              {{ item.currentMembersCount }}/{{ item.maxMembers }}\n            </text>\n          </view>\n\n          <view class=\"creator-info\">\n            <image\n              class=\"creator-avatar\"\n              :src=\"item.creatorAvatar ? item.creatorAvatar : defaultAvatar\"\n              mode=\"aspectFill\"\n            />\n            <text class=\"creator-name\">{{ item.creatorUserName || '匿名用户' }}</text>\n          </view>\n        </view>\n      </view>\n    </view>\n  </view>\n</template>\n\n<script setup>\nimport { ref, watch, onMounted, computed } from 'vue'\n\nconst props = defineProps({\n  modelValue: Array,\n  highlightKeyword: String\n})\n\nconst emit = defineEmits(['update:modelValue', 'itemClick'])\n\nconst flowList = ref(props.modelValue)\n\nonMounted(() => {\n  // console.log('组件初始接收到的数据：', props.modelValue)\n})\n\nwatch(() => props.modelValue, (newVal) => {\n  flowList.value = newVal\n})\n\nwatch(flowList, (newVal) => {\n  emit('update:modelValue', newVal)\n})\n\nconst handleClick = (item) => {\n  emit('itemClick', item)\n}\n\nconst leftList = computed(() =>\n  flowList.value.filter((_, index) => index % 2 === 0)\n)\nconst rightList = computed(() =>\n  flowList.value.filter((_, index) => index % 2 === 1)\n)\n\nconst highlight = (text) => {\n  if (!props.highlightKeyword || !text) return text || ''\n  const regex = new RegExp(`(${props.highlightKeyword})`, 'gi')\n  return text.replace(regex, '<mark>$1</mark>')\n}\n\nconst defaultAvatar = 'https://cdn-icons-png.flaticon.com/512/149/149071.png'\nconst defaultCover = 'https://cdn-icons-png.flaticon.com/512/1055/1055687.png'\n</script>\n\n<style scoped>\n.waterfall-container {\n  display: flex;\n  justify-content: space-between;\n  gap: 16rpx;\n  padding: 16rpx;\n}\n\n.column {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n}\n\n.display-card {\n  margin-bottom: 24rpx;\n  background-color: #ffffff;\n  border-radius: 24rpx;\n  overflow: hidden;\n  box-shadow: 0 12rpx 24rpx rgba(0, 0, 0, 0.1);\n  transition: transform 0.3s ease;\n}\n\n.display-card:hover {\n  transform: translateY(-8rpx);\n}\n\n.cover-wrapper {\n  position: relative;\n  width: 100%;\n  height: 240rpx;\n}\n\n.cover-image {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  display: block;\n}\n\n.overlay {\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  padding: 16rpx;\n  background: linear-gradient(to top, rgba(0, 0, 0, 0.55), transparent);\n}\n\n.overlay .title {\n  font-size: 32rpx;\n  font-weight: bold;\n  color: #fff;\n  text-shadow: 0 0 8rpx rgba(0, 0, 0, 0.5);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.info-section {\n  padding: 24rpx;\n}\n\n.display-field {\n  margin-bottom: 16rpx;\n  display: flex;\n  align-items: flex-start;\n}\n\n.field-name {\n  font-size: 28rpx;\n  color: #555;\n  font-weight: 600;\n  margin-right: 8rpx;\n  white-space: nowrap;\n}\n\n.field-value {\n  font-size: 28rpx;\n  color: #0055aa;\n  word-break: break-word;\n  flex: 1;\n}\n\nmark {\n  background-color: #ffeb3b;\n  color: black;\n  font-weight: bold;\n  padding: 0 4rpx;\n}\n\n.creator-info {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  margin-top: 16rpx;\n}\n\n.creator-avatar {\n  width: 36rpx;\n  height: 36rpx;\n  border-radius: 50%;\n  margin-right: 8rpx;\n}\n\n.creator-name {\n  font-size: 28rpx;\n  color: #333;\n}\n</style>\n","import Component from 'D:/uniapp/myJoinup/joinup/components/WaterfallList.vue'\nwx.createComponent(Component)"],"names":["ref","onMounted","watch","computed"],"mappings":";;AA0IA,MAAM,gBAAgB;AACtB,MAAM,eAAe;;;;;;;;;AAvCrB,UAAM,QAAQ;AAKd,UAAM,OAAO;AAEb,UAAM,WAAWA,cAAAA,IAAI,MAAM,UAAU;AAErCC,kBAAAA,UAAU,MAAM;AAAA,IAEhB,CAAC;AAEDC,kBAAK,MAAC,MAAM,MAAM,YAAY,CAAC,WAAW;AACxC,eAAS,QAAQ;AAAA,IACnB,CAAC;AAEDA,kBAAAA,MAAM,UAAU,CAAC,WAAW;AAC1B,WAAK,qBAAqB,MAAM;AAAA,IAClC,CAAC;AAED,UAAM,cAAc,CAAC,SAAS;AAC5B,WAAK,aAAa,IAAI;AAAA,IACxB;AAEA,UAAM,WAAWC,cAAAA;AAAAA,MAAS,MACxB,SAAS,MAAM,OAAO,CAAC,GAAG,UAAU,QAAQ,MAAM,CAAC;AAAA,IACrD;AACA,UAAM,YAAYA,cAAAA;AAAAA,MAAS,MACzB,SAAS,MAAM,OAAO,CAAC,GAAG,UAAU,QAAQ,MAAM,CAAC;AAAA,IACrD;AAEA,UAAM,YAAY,CAAC,SAAS;AAC1B,UAAI,CAAC,MAAM,oBAAoB,CAAC;AAAM,eAAO,QAAQ;AACrD,YAAM,QAAQ,IAAI,OAAO,IAAI,MAAM,gBAAgB,KAAK,IAAI;AAC5D,aAAO,KAAK,QAAQ,OAAO,iBAAiB;AAAA,IAC9C;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;ACvIA,GAAG,gBAAgB,SAAS;"}
